const goldenProject = "../../testdata/golden"

// TestGoldenOutputs compares the four generated files with
// testdata/golden/want. VELA_APP_UPDATE=1 rewrites them.
func TestGoldenOutputs(t *testing.T) {
	model, diags := Load(goldenProject)
	if len(diags) > 0 {
		t.Fatal(Error(diags))
	}
	outputs, err := model.Outputs()
	if err != nil {
		t.Fatal(err)
	}
	for _, out := range outputs {
		want := filepath.Join(goldenProject, "want", path.Base(out.Path))
		if os.Getenv("VELA_APP_UPDATE") != "" {
			writeFile(t, want, string(out.Data))
			continue
		}
		data, err := os.ReadFile(want)
		if err != nil {
			t.Fatal(err)
		}
		if string(data) != string(out.Data) {
			t.Errorf("%s differs from %s (VELA_APP_UPDATE=1 rewrites it):\n%s", out.Path, want, out.Data)
		}
	}
	// The output does not depend on the walk: a second build is equal.
	again, _ := Load(goldenProject)
	outputs2, _ := again.Outputs()
	for i := range outputs {
		if string(outputs[i].Data) != string(outputs2[i].Data) {
			t.Errorf("%s is not stable", outputs[i].Path)
		}
	}
}

func TestGenerateWritesOnlyChangedFilesAndRemovesStaleOnes(t *testing.T) {
	root := copyProject(t, goldenProject)
	result, diags := Generate(root)
	if len(diags) > 0 {
		t.Fatal(Error(diags))
	}
	if len(result.Written) != 4 {
		t.Fatalf("written %v", result.Written)
	}
	result, _ = Generate(root)
	if len(result.Written) != 0 || len(result.Unchanged) != 4 {
		t.Fatalf("second run: %+v", result)
	}
	// A stale file it owns is removed; a file of the developer is kept.
	writeFile(t, filepath.Join(root, "src/_app/Old.vela"), "<script>\n  // "+Marker+"\n</script>\n")
	writeFile(t, filepath.Join(root, "src/_app/mine.js"), "export const x = 1;\n")
	writeFile(t, filepath.Join(root, "internal/appgen/extra.go"), "// "+Marker+"\n\npackage appgen\n")
	result, _ = Generate(root)
	if strings.Join(result.Removed, ",") != "internal/appgen/extra.go,src/_app/Old.vela" {
		t.Errorf("removed %v", result.Removed)
	}
	if _, err := os.Stat(filepath.Join(root, "src/_app/mine.js")); err != nil {
		t.Errorf("a file without the marker was removed: %v", err)
	}
	// A route change rewrites only the files that depend on it.
	writeFile(t, filepath.Join(root, "src/routes/news/Page.vela"), page)
	result, _ = Generate(root)
	if strings.Join(result.Written, ",") != "src/_app/VelaApp.vela,src/_app/routes.js,internal/appgen/routes_gen.go" {
		t.Errorf("written %v", result.Written)
	}
	// A generated file edited by hand is replaced; one without the marker
	// is an error and nothing is written.
	writeFile(t, filepath.Join(root, "src/_app/client.js"), "// mine\n")
	writeFile(t, filepath.Join(root, "src/routes/more/Page.vela"), page)
	result, diags = Generate(root)
	if len(diags) != 1 || !strings.Contains(diags[0].String(), "src/_app/client.js:1:1: [error] [VELA-APP-CONFIG] the file exists and was not generated by vela-app") {
		t.Fatalf("diagnostics %v", Error(diags))
	}
	if len(result.Written) != 0 {
		t.Errorf("wrote %v despite an error", result.Written)
	}
	// Errors in the routes write nothing either.
	os.Remove(filepath.Join(root, "src/_app/client.js"))
	before, _ := os.ReadFile(filepath.Join(root, "src/_app/routes.js"))
	writeFile(t, filepath.Join(root, "src/routes/[a]-[b]/Page.vela"), page)
	if _, diags := Generate(root); len(diags) == 0 {
		t.Fatal("no error for a mixed segment")
	}
	after, _ := os.ReadFile(filepath.Join(root, "src/_app/routes.js"))
	if string(before) != string(after) {
		t.Error("routes.js changed despite an error")
	}
}

func TestScaffold(t *testing.T) {
	root := copyProject(t, goldenProject)
	created, diags := Scaffold(root, "")
	if len(diags) > 0 {
		t.Fatal(Error(diags))
	}
	want := []string{
		"server/routes/admin.group/load.go",
		"server/routes/admin.group/settings/load.go",
		"server/routes/lang.opt/about/load.go",
		"server/routes/colors/c.hex.param/load.go",
		"server/routes/files/path.rest/load.go",
	}
	if strings.Join(created, "\n") != strings.Join(want, "\n") {
		t.Fatalf("created\n%s\nwant\n%s", strings.Join(created, "\n"), strings.Join(want, "\n"))
	}
	data, _ := os.ReadFile(filepath.Join(root, "server/routes/colors/c.hex.param/load.go"))
	if !strings.Contains(string(data), "package c_hex_param\n") || !strings.Contains(string(data), "func Page(ctx context.Context, r *app.Request) (any, error) {") || strings.Contains(string(data), "func Layout") {
		t.Errorf("load.go:\n%s", data)
	}
	// The scaffolded loaders pass the generator's checks and reach the table.
	model, diags := Load(root)
	if len(diags) > 0 {
		t.Fatal(Error(diags))
	}
	for _, r := range model.Routes {
		if r.ID == "/[[lang]]/about" && r.Chain[len(r.Chain)-1].LoaderPkg != "server/routes/lang.opt/about" {
			t.Errorf("the scaffolded loader is not used: %+v", r.Chain[len(r.Chain)-1])
		}
	}
	// It never overwrites, and one route can be named by its id.
	writeFile(t, filepath.Join(root, "server/routes/lang.opt/about/load.go"), "package about\n")
	if created, _ := Scaffold(root, "/[[lang]]/about"); len(created) != 0 {
		t.Errorf("overwrote: %v", created)
	}
	if data, _ := os.ReadFile(filepath.Join(root, "server/routes/lang.opt/about/load.go")); string(data) != "package about\n" {
		t.Errorf("load.go was changed: %s", data)
	}
	if _, diags := Scaffold(root, "/nope"); len(diags) != 1 {
		t.Errorf("an unknown route: %v", diags)
	}
}

func TestWatchRegenerates(t *testing.T) {
	root := copyProject(t, goldenProject)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	events := make(chan Result, 10)
	errs := make(chan []Diagnostic, 10)
	go Watch(ctx, root, 20*time.Millisecond, func(r Result, d []Diagnostic) {
		if len(d) > 0 {
			errs <- d
			return
		}
		events <- r
	})
	wait := func(what string) Result {
		t.Helper()
		select {
		case r := <-events:
			return r
		case d := <-errs:
			t.Fatalf("%s: %v", what, Error(d))
		case <-time.After(10 * time.Second):
			t.Fatalf("%s: no generation", what)
		}
		return Result{}
	}
	if r := wait("first run"); len(r.Written) != 4 {
		t.Fatalf("first run wrote %v", r.Written)
	}
	writeFile(t, filepath.Join(root, "src/routes/news/Page.vela"), page)
	if r := wait("new route"); len(r.Written) == 0 {
		t.Fatal("a new route regenerated nothing")
	}
	// A loader in the mirrored tree changes routes_gen.go.
	writeFile(t, filepath.Join(root, "server/routes/news/load.go"), loaderImports+"func Page(ctx context.Context, r *app.Request) (any, error) { return nil, nil }\n")
	if r := wait("new loader"); strings.Join(r.Written, ",") != "internal/appgen/routes_gen.go" {
		t.Fatalf("a loader regenerated %v", r.Written)
	}
	// An error is reported, and the next fix regenerates.
	writeFile(t, filepath.Join(root, "server/params/hex/match.go"), "package hex\n")
	select {
	case d := <-errs:
		if !strings.Contains(Error(d).Error(), "VELA-APP-MATCHER") {
			t.Fatalf("errors %v", Error(d))
		}
	case <-time.After(10 * time.Second):
		t.Fatal("no error for a broken matcher")
	}
}

// --- running the compiler and go -----------------------------------------

var (
	velaOnce sync.Once
	velaBin  string
	velaErr  error
)

// velaBinary builds the compiler from the repository: app tests run it as a
// program, never as a Go package (docs/APP.md B-4).
func velaBinary(t *testing.T) string {
	t.Helper()
	velaOnce.Do(func() {
		dir, err := os.MkdirTemp("", "vela-app-test-")
		if err != nil {
			velaErr = err
			return
		}
		velaBin = filepath.Join(dir, "vela")
		if filepath.Separator == '\\' {
			velaBin += ".exe"
		}
		build := exec.Command("go", "build", "-o", velaBin, ".")
		build.Dir = repoRoot(t)
		build.Env = append(os.Environ(), "GOFLAGS=")
		if out, err := build.CombinedOutput(); err != nil {
			velaErr = &exec.ExitError{}
			t.Logf("go build vela: %s", out)
			velaErr = err
		}
	})
	if velaErr != nil {
		t.Fatalf("build vela: %v", velaErr)
	}
	return velaBin
}

func repoRoot(t *testing.T) string {
	root, err := filepath.Abs("../../..")
	if err != nil {
		t.Fatal(err)
	}
	return root
}

// copyProject copies a project into a temporary directory without the
// outputs of vela-app and vela.
func copyProject(t *testing.T, src string) string {
	t.Helper()
	dst := t.TempDir()
	err := filepath.WalkDir(src, func(file string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, file)
		slash := filepath.ToSlash(rel)
		if entry.IsDir() {
			switch slash {
			case "out", "want", "src/_app", "internal/appgen":
				return filepath.SkipDir
			}
			return nil
		}
		data, err := os.ReadFile(file)
		if err != nil {
			return err
		}
		writeFile(t, filepath.Join(dst, rel), string(data))
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return dst
}

// useLocalModules points go.mod of a copied project at the app and runtime
// modules of this repository.
func useLocalModules(t *testing.T, root string) {
	t.Helper()
	repo := repoRoot(t)
	data, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		t.Fatal(err)
	}
	module := strings.SplitN(string(data), "\n", 2)[0]
	app := filepath.ToSlash(filepath.Join(repo, "app"))
	runtime := filepath.ToSlash(filepath.Join(repo, "ssr_runtime"))
	writeFile(t, filepath.Join(root, "go.mod"), module+"\n\ngo 1.25.0\n\nrequire (\n\tgithub.com/elauven/vela/app v0.0.0\n\tgithub.com/elauven/vela/ssr_runtime v0.0.0\n)\n\nreplace (\n\tgithub.com/elauven/vela/app => "+app+"\n\tgithub.com/elauven/vela/ssr_runtime => "+runtime+"\n)\n")
	os.Remove(filepath.Join(root, "go.sum"))
}

func run(t *testing.T, dir, name string, args ...string) string {
	t.Helper()
	command := exec.Command(name, args...)
	command.Dir = dir
	command.Env = append(os.Environ(), "GOWORK=off", "GOFLAGS=-mod=mod")
	out, err := command.CombinedOutput()
	if err != nil {
		t.Fatalf("%s %s: %v\n%s", name, strings.Join(args, " "), err, out)
	}
	return string(out)
}

// buildApp runs the whole chain of docs/APP.md on a project: vela-app gen,
// vela --ssr, go build and go vet.
func buildApp(t *testing.T, root string) {
	t.Helper()
	if _, diags := Generate(root); len(diags) > 0 {
		t.Fatal(Error(diags))
	}
	out := run(t, root, velaBinary(t))
	for _, line := range strings.Split(out, "\n") {
		if strings.Contains(line, " x ") || strings.Contains(line, "✗") || strings.Contains(line, "error") || strings.Contains(line, "warn") {
			t.Errorf("vela: %s", line)
		}
	}
	if !strings.Contains(out, "SSR components emitted") {
		t.Fatalf("vela:\n%s", out)
	}
	useLocalModules(t, root)
	run(t, root, "go", "build", "./...")
	run(t, root, "go", "vet", "./...")
}

func requireGo(t *testing.T) {
	t.Helper()
	if testing.Short() {
		t.Skip("builds the compiler and the generated Go code")
	}
	if _, err := exec.LookPath("go"); err != nil {
		t.Skip("go tool not available")
	}
}

// TestGeneratedAppCompiles compiles the generated VelaApp.vela with the vela
// binary under --ssr without diagnostics, and builds the Go route table
// against the generated renderer and the loaders.
func TestGeneratedAppCompiles(t *testing.T) {
	requireGo(t)
	root := copyProject(t, goldenProject)
	// A main package keeps the route table and the renderer in the build.
	writeFile(t, filepath.Join(root, "cmd/check/main.go"), `package main

import (
	"os"

	"example.com/golden/internal/appgen"
	"github.com/elauven/vela/app"
)

func main() {
	routes := appgen.Routes()
	match, ok := routes.Match("/users/2")
	if !ok || match.Route.ID != "/users/[id=int]" || match.Route.Render != app.RenderFragment {
		panic("match")
	}
	chain := []any{
		map[string]any{"id": "routes/Layout", "data": map[string]any{"title": "Golden"}},
		map[string]any{"id": "routes/users/Layout", "data": map[string]any{"count": 2.0}},
		map[string]any{"id": "routes/users/[id=int]/Page", "data": map[string]any{"name": "Ada"}},
	}
	route := map[string]any{"path": "/users/2", "params": map[string]any{"id": "2"}}
	if err := routes.Root.Render(os.Stdout, app.RootProps{Route: route, Chain: chain}); err != nil {
		panic(err)
	}
}
`)
	buildApp(t, root)
	html := run(t, root, "go", "run", "./cmd/check")
	for _, want := range []string{
		"<nav>Golden /users/2</nav>",
		`<div class="users"><p>2</p>`,
		"<h1>Ada 2</h1>",
		`["d","VelaApp#0","routes/Layout"]`,
		`["d","VelaApp#2","routes/users/[id=int]/Page"]`,
	} {
		if !strings.Contains(html, want) {
			t.Errorf("server HTML misses %q:\n%s", want, html)
		}
	}
}

// TestExampleApp is the acceptance check of task 074: vela-app gen, vela
// --ssr, go build and go vet succeed on examples/app.
func TestExampleApp(t *testing.T) {
	requireGo(t)
	root := copyProject(t, filepath.Join(repoRoot(t), "examples", "app"))
	buildApp(t, root)
	out := run(t, root, "go", "run", "./cmd/routes", "/", "/users/2", "/users/x", "/de/about", "/settings", "/colors/00ff00", "/nope")
	want := "/\t/\tmap[]\n" +
		"/users/2\t/users/[id=int]\tmap[id:2]\n" +
		"/users/x\t404\n" +
		"/de/about\t/[[lang]]/about\tmap[lang:de]\n" +
		"/settings\t/(admin)/settings\tmap[]\n" +
		"/colors/00ff00\t/colors/[hex=color]\tmap[hex:00ff00]\n" +
		"/nope\t404\n"
	if out != want {
		t.Errorf("routes:\n%s\nwant\n%s", out, want)
	}
}
